  SELECT 1
  UNION ALL
  SELECT n * 2 FROM r WHERE n < 20
)
SELECT string_agg(n::text, ',' ORDER BY n) FROM r;

CREATE TEMP TABLE emp (id int, boss int);
INSERT INTO emp VALUES (1, NULL), (2, 1), (3, 1), (4, 2), (5, 4);
WITH RECURSIVE tree AS (
  SELECT id, 0 AS depth FROM emp WHERE boss IS NULL
  UNION ALL
  SELECT e.id, t.depth + 1 FROM emp e JOIN tree t ON e.boss = t.id
)
SELECT depth, count(*) FROM tree GROUP BY depth ORDER BY depth;

CREATE TEMP TABLE cat (id int, name text, parent int);
INSERT INTO cat VALUES (1, 'root', NULL), (2, 'bin', 1), (3, 'usr', 1), (4, 'lib', 3);
WITH RECURSIVE p AS (
  SELECT id, name AS path FROM cat WHERE parent IS NULL
  UNION ALL
  SELECT c.id, p.path || '/' || c.name FROM cat c JOIN p ON c.parent = p.id
)
SELECT path FROM p ORDER BY path;

